// Pinlarni aniqlab olamiz
const int pinQizil = 3;
const int pinSariq = 4;
const int pinYashil = 5;

void setup() {
  // Barcha pinlarni chiqish (OUTPUT) rejimiga o'rnatamiz
  pinMode(pinQizil, OUTPUT);
  pinMode(pinSariq, OUTPUT);
  pinMode(pinYashil, OUTPUT);
}

void loop() {
  // 1. QIZIL chiroq yonadi (To'xtang)
  digitalWrite(pinQizil, HIGH);
  digitalWrite(pinSariq, LOW);
  digitalWrite(pinYashil, LOW);
  delay(4000); // 4 soniya kutish

  // 2. Qizil + SARIQ yonadi (Tayyorlaning)
  digitalWrite(pinQizil, HIGH);
  digitalWrite(pinSariq, HIGH);
  digitalWrite(pinYashil, LOW);
  delay(1000); // 1 soniya kutish

  // 3. YASHIL chiroq yonadi (Harakatlaning)
  digitalWrite(pinQizil, LOW);
  digitalWrite(pinSariq, LOW);
  digitalWrite(pinYashil, HIGH);
  delay(4000); // 4 soniya kutish

  // 4. YASHIL miltillaydi (O'chishidan oldin ogohlantirish)
  for (int i = 0; i < 4; i++) {
    digitalWrite(pinYashil, LOW);
    delay(250);
    digitalWrite(pinYashil, HIGH);
    delay(250);
  }

  // 5. SARIQ chiroq yonadi (Diqqat, to'xtang)
  digitalWrite(pinQizil, LOW);
  digitalWrite(pinSariq, HIGH);
  digitalWrite(pinYashil, LOW);
  delay(1500); // 1.5 soniya kutish
}
